import {
  type Completion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import { pythonLanguage } from "@codemirror/lang-python";
import type { Extension } from "@codemirror/state";
import { type Parser, parseMixed } from "@lezer/common";
import { tags } from "@lezer/highlight";
import type {
  DelimiterType,
  InlineContext,
  MarkdownConfig,
  NodeSpec,
} from "@lezer/markdown";
import { store } from "@/core/state/jotai";
import { variablesAtom } from "@/core/variables/state";

// Node names for the embedded Python expression and its delimiters.
const PYTHON = "Python";
const PYTHON_MARK = "PythonMark";

// Character codes for the curly braces that delimit an interpolation block.
const CHARS_CODES = {
  OPEN_CURLY: 123, // {
  CLOSE_CURLY: 125, // }
};

/**
 * Delimiter used to wrap an embedded Python interpolation block.
 */
const PYTHON_DELIMITER: DelimiterType = {
  mark: PYTHON_MARK,
  resolve: PYTHON,
};

/**
 * Define a parser for embedded Python interpolation blocks (e.g. `{ x }`)
 * inside Markdown.
 *
 * @param pythonParser CodeMirror {@link Parser} for Python
 * @param isActivated whether the embedded Python parsing is active
 * @returns Markdown extension
 */
export function parsePython(
  pythonParser: Parser,
  isActivated: () => boolean,
): MarkdownConfig {
  const defineNodes: NodeSpec[] = [
    { name: PYTHON, style: tags.emphasis },
    { name: PYTHON_MARK, style: tags.processingInstruction },
  ];

  return {
    defineNodes,
    parseInline: [
      {
        name: PYTHON,
        parse(cx: InlineContext, next: number, pos: number): number {
          // Do not parse if embedded Python is not activated.
          if (!isActivated()) {
            return -1;
          }

          const isOpen = next === CHARS_CODES.OPEN_CURLY;
          const isClose = next === CHARS_CODES.CLOSE_CURLY;

          // Only curly braces can start/end an interpolation block.
          if (!isOpen && !isClose) {
            return -1;
          }

          // A double open curly brace (`{{`) is an escape sequence, not an
          // interpolation block.
          if (isOpen && cx.char(pos + 1) === CHARS_CODES.OPEN_CURLY) {
            return -1;
          }

          // Likewise, a double close curly brace (`}}`) is an escape sequence.
          if (isClose && cx.char(pos + 1) === CHARS_CODES.CLOSE_CURLY) {
            return -1;
          }

          return cx.addDelimiter(PYTHON_DELIMITER, pos, pos + 1, isOpen, isClose);
        },
      },
    ],
    wrap: parseMixed((node) => {
      if (node.type.name !== PYTHON) {
        return null;
      }

      // Strip the surrounding curly braces before handing off to Python.
      const from = node.from + 1;
      const to = node.to - 1;

      // Ensure valid ranges
      if (from >= to || from < 0 || to < 0) {
        return null;
      }

      return {
        parser: pythonParser,
        overlay: [{ from, to }],
      };
    }),
  };
}

/**
 * Provides variable-name completions for embedded Python interpolation blocks.
 *
 * This relies on the Python language overlay produced by {@link parsePython},
 * so it is registered as Python language data.
 */
export function embeddedPythonCompletions(
  isActivated: () => boolean,
): Extension {
  return [
