import { describe, expect, it } from "vitest";
import { CompletionContext } from "@codemirror/autocomplete";
import { EditorState } from "@codemirror/state";
import { store } from "@/core/state/jotai";
import { variablesAtom } from "@/core/variables/state";
import type { Variables } from "@/core/variables/types";
import {
  embeddedPythonCompletions,
  parsePython,
  variableCompletionSource,
} from "./embedded-python";
import { parser as pythonParser } from "@lezer/python";

function ctx(doc: string, pos: number, explicit = false) {
  const state = EditorState.create({ doc });
  return new CompletionContext(state, pos, explicit);
}

describe("scratch embedded-python", () => {
  store.set(variablesAtom, {
    foo: { name: "foo", declaredBy: [], usedBy: [], dataType: "int" },
    bar: { name: "bar", declaredBy: [], usedBy: [] },
  } as unknown as Variables);

  it("parsePython config shape", () => {
    const cfg = parsePython(pythonParser, () => true);
    expect(cfg.defineNodes?.map((n) => (n as { name: string }).name)).toEqual([
      "Python",
      "PythonMark",
    ]);
    const parse = cfg.parseInline![0].parse;
    // not activated -> -1
    const cfgOff = parsePython(pythonParser, () => false);
    const fakeCx = { char: () => 0 } as never;
    expect(cfgOff.parseInline![0].parse(fakeCx, 123, 0)).toBe(-1);
    // double open brace -> -1
    const dbl = { char: (p: number) => (p === 1 ? 123 : 0) } as never;
    expect(parse(dbl, 123, 0)).toBe(-1);
    // non-brace -> -1
    expect(parse({ char: () => 0 } as never, 97, 0)).toBe(-1);
  });

  it("variableCompletionSource inside braces", () => {
    const r = variableCompletionSource(ctx("{ fo", 4));
    expect(r).not.toBeNull();
    expect(r?.options.map((o) => o.label).sort()).toEqual(["bar", "foo"]);
    expect(r?.from).toBe(2);
  });

  it("variableCompletionSource null cases", () => {
    expect(variableCompletionSource(ctx("foo", 3))).toBeNull(); // no open brace
    expect(variableCompletionSource(ctx("{ foo } ba", 10))).toBeNull(); // closed
    expect(variableCompletionSource(ctx("{{ fo", 5))).toBeNull(); // double brace
    expect(variableCompletionSource(ctx("{ ", 2))).toBeNull(); // no word
  });

  it("embeddedPythonCompletions gating", () => {
    const off = embeddedPythonCompletions(() => false);
    expect(Array.isArray(off)).toBe(true);
    // The facet autocomplete lives inside; just ensure it is an array extension
    const on = embeddedPythonCompletions(() => true);
    expect(Array.isArray(on)).toBe(true);
  });
});
